package hu.synostream.android;
import androidx.test.ext.junit.runners.AndroidJUnit4;import androidx.test.platform.app.InstrumentationRegistry;import androidx.test.uiautomator.*;import org.json.*;import org.junit.*;import org.junit.runner.RunWith;import static org.junit.Assert.*;import java.io.*;import java.nio.charset.StandardCharsets;import java.util.*;import java.util.concurrent.*;
@RunWith(AndroidJUnit4.class) public class Android0511Test {
 final Android050FlowTest f=new Android050FlowTest();JSONObject library;File original;byte[] originalBytes;
 @Before public void init(){f.instrumentation=InstrumentationRegistry.getInstrumentation();f.context=f.instrumentation.getTargetContext();f.app=(SynoApp)f.context.getApplicationContext();f.device=UiDevice.getInstance(f.instrumentation);UiLocale.save(f.context,"hu");}
 @After public void cleanup()throws Exception{f.instrumentation.runOnMainSync(()->{f.app.cancelScan();f.app.epoch++;f.app.libraryDraft=null;});f.cleanup();}
 void setup(FakeNas nas)throws Exception{Library.Card cached=new Library.Card("/Movies/Demo.Movie.2020.mkv","Cached fixture",true);f.setup(nas,List.of(cached));library=new JSONObject(f.app.selected().toString()).put("id","cache-key-fixture").put("name","Cache fixture").put("builtin",false);f.instrumentation.runOnMainSync(()->{f.app.libraries.put(library);f.app.selectedLibrary=library.optString("id");});original=f.app.cacheFile(library);originalBytes=new JSONArray().put(cached.json()).toString().getBytes(StandardCharsets.UTF_8);try(FileOutputStream out=new FileOutputStream(original)){out.write(originalBytes);}nas.holdListResponse=true;}
 void edit(){MainActivity activity=f.activity();f.instrumentation.runOnMainSync(()->new LibraryUi(activity).edit(f.app.selected()));assertTrue(f.device.wait(Until.hasObject(By.res(f.pkg+":id/library_save")),10000));}
 void save()throws Exception{f.click("library_save");assertTrue(f.device.wait(Until.gone(By.res(f.pkg+":id/library_save")),10000));f.instrumentation.waitForIdleSync();CountDownLatch drained=new CountDownLatch(1);f.app.cacheIo.execute(()->f.app.main.post(drained::countDown));assertTrue(drained.await(10,TimeUnit.SECONDS));}
 void unchangedCache(FakeNas nas)throws Exception{assertEquals(1,nas.listRequestRead.getCount());assertFalse(f.app.scanRunning);assertFalse(f.app.busy);assertEquals("Cached fixture",f.app.cards.get(0).title);assertTrue(original.exists());assertArrayEquals(originalBytes,NasClient.readBounded(new FileInputStream(original),20*1024*1024));}
 @Test public void renameRetainsWarmCacheWithoutAnyFolderListRequest()throws Exception{try(FakeNas nas=new FakeNas()){try{setup(nas);edit();f.device.findObject(By.res(f.pkg+":id/library_name")).setText("Renamed cache fixture");save();unchangedCache(nas);assertEquals("Renamed cache fixture",f.app.selected().optString("name"));assertEquals(original,f.app.cacheFile(f.app.selected()));}finally{nas.releaseListResponse.countDown();}}}
 @Test public void unchangedSaveRetainsWarmCacheWithoutAnyFolderListRequest()throws Exception{try(FakeNas nas=new FakeNas()){try{setup(nas);edit();save();unchangedCache(nas);assertEquals(original,f.app.cacheFile(f.app.selected()));}finally{nas.releaseListResponse.countDown();}}}
 @Test public void changingSourceRemovesOldCacheAndStartsScan()throws Exception{try(FakeNas nas=new FakeNas()){try{setup(nas);nas.folders.add("/Other");nas.files.put("/Other/Other.Movie.2020.mkv",new byte[]{1});edit();f.instrumentation.runOnMainSync(()->{try{LibraryConfig.paths(f.app.libraryDraft,List.of("/Other"));}catch(Exception e){throw new RuntimeException(e);}});save();assertTrue("Changed source must start a scan",nas.listRequestRead.await(10,TimeUnit.SECONDS));assertFalse(original.exists());assertNotEquals(original,f.app.cacheFile(f.app.selected()));assertEquals(List.of("/Other"),LibraryConfig.paths(f.app.selected()));nas.releaseListResponse.countDown();long deadline=System.currentTimeMillis()+20000;while(f.app.busy&&System.currentTimeMillis()<deadline)Thread.sleep(25);assertFalse(f.app.busy);assertEquals(1,f.app.rawCards.size());assertTrue(f.app.rawCards.get(0).path.startsWith("/Other/"));}finally{nas.releaseListResponse.countDown();}}}
}
